const carte = document.querySelector("#carte");
const bouton = document.querySelector("#choisir");
const retour = document.querySelector("#retour");
let retenu = carte.dataset.retenu === "true";
function rendre() {
  carte.classList.toggle("retenu", retenu);
  carte.dataset.retenu = String(retenu);
  bouton.setAttribute("aria-pressed", String(retenu));
  if (retenu) { retour.textContent = "Retenu."; }
  else { retour.textContent = "Non retenu."; }
}
bouton.addEventListener("click", function() { retenu = !retenu; rendre(); });
rendre();

